import os, subprocess, json, base64, zlib, re
P='/tmp/probe/env-diff'
BASE=dict(HOME=P+'/home', PATH='/usr/bin:/bin', TERM='xterm')
def gz(s):
    s=s.strip(); s+='='*(-len(s)%4)
    return json.loads(zlib.decompress(base64.urlsafe_b64decode(s)))
def enc(o):
    raw=zlib.compress(json.dumps(o,separators=(',',':')).encode())
    return base64.urlsafe_b64encode(raw).decode().rstrip('=')
def mk(name, body, allow=True):
    wd=os.path.join(P,'t',name); os.makedirs(wd,exist_ok=True)
    open(os.path.join(wd,'.envrc'),'w').write(body)
    if allow: subprocess.run(['/workspace/executable','allow'],cwd=wd,env=dict(BASE,PWD=wd),capture_output=True)
    return wd
def run(wd, extra=None, *args):
    e=dict(BASE); e['PWD']=wd
    if extra: e.update(extra)
    return subprocess.run(['/workspace/executable',*args],cwd=wd,env=e,capture_output=True,text=True)
def show(p,label=''):
    print('### '+label+'  exit=%d'%p.returncode)
    print('--stderr--'); print(repr(p.stderr))
    print('--stdout--'); print(p.stdout if len(p.stdout)<4000 else p.stdout[:4000]+'...')
def jdiff(p):
    j=json.loads(p.stdout)
    d=gz(j['DIRENV_DIFF'])
    return j,d
EOS
